mapper.select:
SELECT c.id,c.position AS number,c.title FROM chapters c LEFT JOIN chapter_progress p ON p.chapter_id=c.id AND p.member_id=#{memberId}
WHERE c.offering_id=#{offeringId} AND c.status='published'
ORDER BY CASE WHEN c.id=#{lastChapterId} THEN 0 WHEN p.status IS NULL OR p.status!='completed' THEN 1 ELSE 2 END,c.position,c.id LIMIT 1
